ReplacementChunks.ReplacementContent:
{/* Badge PRO cuando el usuario está en el límite */}
{isAtLimit && (
  <View style={{
    position: 'absolute', top: -6, alignSelf: 'center',
    backgroundColor: theme.colors.surface,
    borderRadius: 8, paddingHorizontal: 6, paddingVertical: 1.5,
    borderWidth: 1, borderColor: theme.colors.outlineVariant,
    ...theme.shadows.xs,
  }}>
    <Text style={{ fontSize: 7.5, fontWeight: '900', color: theme.colors.primary, letterSpacing: 0.5, fontFamily: theme.fonts.headline }}>PRO</Text>
  </View>
)}

ReplacementChunks.TargetContent:
{/* Badge PRO cuando el usuario está en el límite */}
{isAtLimit && (
  <View style={{
    position: 'absolute', top: -5, right: -5,
