    borderRadius: 8, paddingHorizontal: 4, paddingVertical: 2,
    flexDirection: 'row', alignItems: 'center', gap: 1.5,
  }}>
    <Lock size={6} color={theme.colors.onPrimary} strokeWidth={3} />
